CREATE TABLE [purchase].[SupplierDocuments] ([DocumentId] UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_SupplierDocuments_Id] DEFAULT NEWSEQUENTIALID(), [SupplierId] UNIQUEIDENTIFIER NOT NULL, [DocumentType] NVARCHAR(50) NOT NULL, [FileName] NVARCHAR(255) NOT NULL, [ContentType] NVARCHAR(100) NOT NULL, [DocumentData] VARBINARY(MAX) NOT NULL, [UploadedOn] DATETIMEOFFSET NOT NULL CONSTRAINT [DF_SupplierDocuments_UploadedOn] DEFAULT SYSUTCDATETIME(), [UploadedBy] NVARCHAR(256) NULL, [IsDeleted] BIT NOT NULL CONSTRAINT [DF_SupplierDocuments_IsDeleted] DEFAULT 0, [RowVersion] ROWVERSION NOT NULL, CONSTRAINT [PK_SupplierDocuments] PRIMARY KEY ([DocumentId]), CONSTRAINT [FK_SupplierDocuments_Suppliers] FOREIGN KEY ([SupplierId]) REFERENCES [purchase].[Suppliers]([SupplierId]) ON DELETE CASCADE, CONSTRAINT [CK_SupplierDocuments_Type] CHECK ([DocumentType]='Other' OR [DocumentType]='Agreement' OR [DocumentType]='Cancelled Cheque' OR [DocumentType]='MSME Certificate' OR [DocumentType]='PAN Card' OR [DocumentType]='GST Certificate'));
GO
CREATE INDEX [IX_SupplierDocuments_SupplierId] ON [purchase].[SupplierDocuments]([SupplierId],[IsDeleted]);
